import { type FileUploadRequest, type FileUploadResponse } from '~/client';
import { Capacitor, CapacitorHttp } from '@capacitor/core';

export interface UploadProgress {
  loaded: number;
  total: number;
  percentage: number;
}

function blobToBase64(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

async function uploadNative(blob: Blob, url: string, headers: Record<string, string>): Promise<FileUploadResponse> {
  const boundary = `----FormBoundary${Date.now()}`;
  const response = await CapacitorHttp.request({
    url,
    method: 'POST',
    headers: { ...headers, 'Content-Type': `multipart/form-data; boundary=${boundary}` },
    data: [
      {
        key: 'file',
        value: await blobToBase64(blob),
        type: 'base64File',
        contentType: blob.type || 'application/octet-stream',
        fileName: blob instanceof File && blob.name ? blob.name : 'upload',
      },
    ],
    dataType: 'formData',
  });

  if (response.status >= 200 && response.status < 300) {
    return response.data as FileUploadResponse;
  }
  throw new Error(`Upload failed with status ${response.status}`);
}

// TODO: use it on import Ballots
export const useUploadFile = defineMutation(() => {
  const progress = ref<UploadProgress>({ loaded: 0, total: 0, percentage: 0 });

  const { mutateAsync: uploadFileData, asyncStatus } = useMutation({
    mutation: async (applicationForm: FileUploadRequest) => {
      progress.value = { loaded: 0, total: 0, percentage: 0 };

      const { token } = useAuth();
      const baseURL = useRuntimeConfig().public.apiBaseURL as string;
      const url = `${baseURL}/api/upload/`;
      const headers: Record<string, string> = token.value ? { Authorization: token.value } : {};

      if (Capacitor.isNativePlatform()) {
        const result = await uploadNative(applicationForm.file, url, headers);
        progress.value = { loaded: 1, total: 1, percentage: 100 };
        return result;
      }

      return new Promise<FileUploadResponse>((resolve, reject) => {
        const xhr = new XMLHttpRequest();

        xhr.upload.addEventListener('progress', (event) => {
          if (event.lengthComputable) {
            progress.value = {
              loaded: event.loaded,
              total: event.total,
              percentage: Math.round((event.loaded / event.total) * 100),
            };
          }
        });

        xhr.addEventListener('load', () => {
          if (xhr.status >= 200 && xhr.status < 300) {
            try {
              resolve(JSON.parse(xhr.responseText) as FileUploadResponse);
            } catch {
              reject(new Error('Failed to parse upload response'));
            }
          } else {
            reject(new Error(`Upload failed with status ${xhr.status}`));
          }
        });

        xhr.addEventListener('error', () => reject(new Error('Upload failed')));
        xhr.addEventListener('abort', () => reject(new Error('Upload aborted')));

        xhr.open('POST', url);
        if (token.value) xhr.setRequestHeader('Authorization', token.value);

        const formData = new FormData();
        formData.append('file', applicationForm.file);
        xhr.send(formData);
      });
    },
    onError: (error) => {
      console.error('Error while uploading file:', error);
    },
  });

  return {
    uploadFileData,
    uploadProgress: progress,
    isFileUploads: computed(() => asyncStatus.value === 'loading'),
  };
});
